import 'package:sqlite3/sqlite3.dart';

void main() {
  final db = sqlite3.open('test.db');
  db.execute('CREATE TABLE users (id INTEGER NOT NULL PRIMARY KEY, name TEXT) STRICT');
  db.execute('INSERT INTO users (name) VALUES (?)', ['SQLite user']);
  print(db.select('SELECT * FROM users'));
}
